schemas:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Is this page replacing the old About page?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. This direction combines About, Team, Process, Why VNW Media, and Our Approach into one stronger Our Story page."
      }
    },
    {
      "@type": "Question",
      "name": "Why keep Our Story as one page?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Company information is easier to digest when it reads like one clear narrative instead of forcing visitors through several small pages."
      }
    },
    {
      "@type": "Question",
      "name": "What should visitors understand after reading it?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "They should know what VNW Media does, how the team thinks, why the process is structured, who the agency helps, and how to take the next step."
      }
    },
    {
      "@type": "Question",
      "name": "Does this help SEO and AI visibility?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. A complete Our Story page can naturally include brand/entity context, services, industries, process language, trust signals, FAQs, and internal links."
      }
    },
    {
      "@type": "Question",
      "name": "What CTA should this page push?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The strongest CTA is a free audit or strategy request because the page is aimed at visitors deciding whether VNW is the right partner."
      }
    },
    {
      "@type": "Question",
      "name": "Can this design become the final Our Story page?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. This version is now the direct Our Story destination in the main navigation."
      }
    }
  ]
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What types of work does VNW Media create?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "VNW Media creates custom websites, local SEO foundations, lead-generation landing pages, Google PPC campaign paths, social content systems, reputation-focused pages, eCommerce experiences, and digital strategy for local and service-based businesses."
      }
    },
    {
      "@type": "Question",
      "name": "Do you only design websites?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. The website is usually the center of the system, but the work often includes messaging, SEO structure, conversion strategy, content, reputation signals, campaign alignment, and post-launch improvement planning."
      }
    },
    {
      "@type": "Question",
      "name": "Can VNW redesign an existing website?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. VNW can improve an existing website or create a new build when the current structure, messaging, speed, design, or conversion path is limiting growth."
      }
    },
    {
      "@type": "Question",
      "name": "Which industries does VNW support?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The portfolio includes automotive, home services, daycare, healthcare, restaurants, eyecare, real estate, legal, retail, professional services, and local businesses that need stronger visibility and lead flow."
      }
    },
    {
      "@type": "Question",
      "name": "How long does a website or marketing project take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Timing depends on scope, content, functionality, approvals, and integrations. After discovery, VNW provides a practical project plan with clear phases and responsibilities."
      }
    },
    {
      "@type": "Question",
      "name": "Can results be measured after launch?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. When tracking and platform access are available, the work can be evaluated through relevant signals such as calls, forms, appointment actions, visibility, engagement, sales, or lead quality."
      }
    },
    {
      "@type": "Question",
      "name": "How should a business start?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Start with a review of the current website, business goals, customer journey, service areas, and marketing channels. From there, VNW can recommend the right scope and priority order."
      }
    }
  ]
}
